window.DATA={"meta":{"title":"Delitto a Villa Malanotte","subtitle":"Cena con delitto · Halloween 2026"},"pub":{"tony":{"name":"Tony","g":"m","img":"img/p-tony.jpg","partner":"noemi","title":"Il Vampiro degli Affari","costume":"Vampiro: mantello nero foderato di rosso","dress":"qualcosa di nero e, se ce l'hai, un mantello (anche un lenzuolo nero va benissimo) 🧛","blurb":"Imprenditore, papà, dorme quattro ore a notte e il telefono gli squilla sempre. Parla di sé in terza persona. Vuole comprare Villa Malanotte per farne la location di eventi più \"mega\" della Sicilia. Don Saverio gli ha sempre risposto di no."},"noemi":{"name":"Noemi","g":"f","img":"img/p-noemi.jpg","partner":"tony","title":"La Strega della Cassa","costume":"Strega: cappello a punta con stelline d'oro, braccialetti, glitter dorato","dress":"qualcosa di nero, tanti braccialetti e un tocco di glitter dorato ✨","blurb":"Cassiera al supermercato del paese: bellissima, monella, con un sorriso che disarma. Alla sua cassa passa la spesa di tutti… quindi sa tutto di tutti. Don Saverio era il suo cliente più affezionato: ogni mattina passava solo per salutarla."},"francesca":{"name":"Francesca","g":"f","img":"img/p-francesca.jpg","partner":"simone","title":"Madame Sole e Luna","costume":"Cartomante: viso metà sole dorato e metà luna d'argento, foulard con monetine","dress":"un foulard, qualche braccialetto e, se ti va, un trucco metà oro e metà argento 🌗","blurb":"Cartomante. Il suo umore cambia come la luna: o è raggiante come il Sole, o è nera come la notte. Parla poco, ma quando si lamenta… si lamenta con Simone. Ogni giovedì leggeva i tarocchi a Don Saverio, che non faceva un passo senza chiedere alle carte."},"simone":{"name":"Simone","g":"m","img":"img/p-simone.jpg","partner":"francesca","title":"Il Semidio del Giardino","costume":"Calciatore zombie: maglia n. 9 strappata, finto sangue, cesoie","dress":"una maglia da calcio (meglio se un po' rovinata) ⚽🧟","blurb":"La mattina fa il giardiniere a Villa Malanotte, la domenica è il centravanti della squadra del paese. Fortissimo, ma il divano è il suo habitat naturale. Conosce ogni siepe, ogni attrezzo e ogni angolo buio del giardino."},"lorenzo":{"name":"Lorenzo","g":"m","img":"img/p-lorenzo.jpg","partner":"claudia","title":"Lo Scheletro Fidato","costume":"Scheletro: abito nero con le ossa, occhiali tondi","dress":"qualcosa di nero e, se vuoi, un po' di trucco bianco da teschio 💀","blurb":"Il braccio destro di Tony: lavora con lui e intanto studia Giurisprudenza. Tony parla, Lorenzo fa. Fa pratica in uno studio notarile di Lentini: conosce carte, firme… e testamenti."},"claudia":{"name":"Claudia","g":"f","img":"img/p-claudia.jpg","partner":"lorenzo","title":"La Gatta Nera","costume":"Gatta nera: orecchie, guanti di velluto, baffi disegnati","dress":"qualcosa di nero e due baffi da gatta disegnati 🐈‍⬛","blurb":"Studentessa di Psicologia, fidanzata di Lorenzo. Sta scrivendo la tesi sulla paura della morte e da mesi, ogni martedì, ascoltava Don Saverio raccontare i suoi incubi. Legge le persone come libri aperti."}},"npc":{"saverio":{"name":"Don Saverio Malanotte","img":"img/n-saverio.jpg","blurb":"79 anni, \"il Barone delle arance\". Ricchissimo, eccentrico, ossessionato dalla notte dei morti. Senza figli. Non perdona chi lo prende in giro."},"calogero":{"name":"Calogero","img":"img/n-calogero.jpg","blurb":"Il maggiordomo. 70 anni, da 40 al servizio del Barone. Sordo da un orecchio, memoria di ferro."}},"facts":["21:00 — Cena. Don Saverio brinda: «A mezzanotte apro la busta nera con il mio nuovo testamento».","21:40 — Don Saverio sale nel suo studio, in cima alla torre.","22:00 — Calogero gli porta la tisana. Il Barone è vivo e sta scrivendo.","22:00–22:40 — Si alzano da tavola: Claudia (22:15), Francesca (22:25), Simone (22:30, verso il giardino), Lorenzo (22:32, verso il cortile).","22:40 — Un fulmine: blackout di 7 minuti. Noemi: «Vado io a prendere le candele!»","22:47 — Torna la luce.","22:55 — Calogero sale a ritirare la tazza e trova Don Saverio morto."],"vote":{"suspects":["tony","noemi","francesca","simone","lorenzo","claudia","calogero"],"questions":[{"id":"killer","q":"Chi ha ucciso Don Saverio?","pts":3},{"id":"drug","q":"Chi ha drogato la tisana?","pts":1},{"id":"thief","q":"Chi ha rubato il testamento?","pts":1},{"id":"actor","q":"Miglior attore/attrice della serata (non tu)","pts":0,"players":true}]},"topic":"vmn-cb7rq3jvitvm","scene":{"villa":"img/s-villa.jpg","cena":"img/s-cena.jpg"},"p":{"72a79850b2739e23":"","b8dd3438892d6c96":"","b82bb40c76ae018d":"","3c84051d02bf95e4":"","21fbb0f9ddc410ed":"","03d8a7cdbb68e92b":""},"h":{"dbd47ac39ac9da9e":""},"v":1793474792960};
